-- News articles from the old website (afrofoot.club, WordPress), imported once. Generated by scripts/import-old-news.py.
-- Paste into Supabase → SQL Editor and run. Safe to run again: existing articles (same slug) are left as they are.
-- Pictures are part of the website (apps/web/public/news/…); the original dates are kept.

insert into news_posts (slug, title, excerpt, body_md, cover_path, status, published_at) values (
  'tat-international-cup-2021-opning-game', 'TAT International CUP 2021, Opning game', 'Exactly 1 week from today, the tournament, we all be waiting for, will start with the defending champion Team KENYA facing AFRO FOOT @16.30 pm , followed by 2 newcomers…',
  'Exactly 1 week from today, the tournament, we all be waiting for, will start with the defending champion Team KENYA facing AFRO FOOT @16.30 pm , followed by 2 newcomers to the competition: WEST AFRICANS vs SOUTH ASIANS LEIJONAT 18.30 pm.
Things to remember and to expect:
*The tournament is from 30.6 – 24.7 with 1 week break(12-18.7)
* All games are being played @Talin Tekonurmikenttä (Address: Purotie 8, 00380 Helsinki)
* Weekdays games always start @16:30 pm and weekends games start @16 pm
*There are always 2 games per day
* Everyone is welcome to come watch the games (we follow the officials guidelines: IF FEELING SICK, PLEASE STAY HOME)
* Games will also be stream through our facebook page (so no one is left behind)
* We all can expect a nice and safe event for all
* Great Games
* Good Music
* Good Food from the community Teams playing
* Activities for Kids (on designated days)
* And plenty more …….
Would we see you? Who you pick, to win this year edition?
Rendez-vous when all begin: 30.6.2021 @16.30 pm

#AfroFoot, #TATInternationalCUP',
  '/news/tat-international-cup-2021-opning-game/cover.jpg', 'published', '2021-06-23T10:46:47Z')
on conflict (slug) do nothing;

