insert into news_posts (slug, title, excerpt, body_md, cover_path, status, published_at) values (
  'afro-award-2023-team-player', 'Afro Award 2023 – Team Player', 'In these last few days of 2023, Afro Foot Club presents its heroes of the 2023 season; Jesper Sjöblom joined Afro Foot Club in March 2023 and won his first…',
